use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{SystemTime, UNIX_EPOCH};

use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

#[derive(Clone, Debug)]
pub struct UserSession {
    pub user_id: String,
    pub balance_cents: i64,
    pub tier: SubscriptionTier,
    pub token_issued_at: u64,
    pub last_payment_nonce: u64,
}

#[derive(Clone, Debug, PartialEq)]
pub enum SubscriptionTier {
    Free,
    Premium,
    Enterprise,
}

#[derive(Clone, Debug)]
pub struct PaymentRequest {
    pub user_id: String,
    pub amount_cents: i64,
    pub nonce: u64,
    pub service_signature: Vec<u8>,
    pub channel_id: String,
}

#[derive(Clone, Debug)]
pub struct ChatMessage {
    pub sender_id: String,
    pub channel_id: String,
    pub content: String,
    pub is_premium_channel: bool,
}

pub struct ChatServer {
    sessions: Arc<RwLock<HashMap<String, UserSession>>>,
    payment_log: Arc<RwLock<Vec<(String, i64, u64)>>>,
    service_keys: Arc<HashMap<String, Vec<u8>>>,
}

impl ChatServer {
    pub fn new(service_keys: HashMap<String, Vec<u8>>) -> Self {
        ChatServer {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            payment_log: Arc::new(RwLock::new(Vec::new())),
            service_keys: Arc::new(service_keys),
        }
    }

    pub fn authenticate_session(&self, user_id: &str, token_data: &[u8]) -> Result<(), String> {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);

        let session = UserSession {
            user_id: user_id.to_string(),
            balance_cents: 0,
            tier: SubscriptionTier::Free,
            token_issued_at: now,
            last_payment_nonce: 0,
        };

        let mut sessions = self.sessions.write().unwrap();
        sessions.insert(user_id.to_string(), session);
        Ok(())
    }

    /// Validates that the payment nonce is fresh and processes the credit.
    /// Cross-service auth: the payment service signs requests with HMAC.
    pub fn process_payment(&self, req: &PaymentRequest) -> Result<String, String> {
        // Verify service signature
        if !self.verify_service_auth(&req.service_signature, &req.user_id, req.amount_cents, req.nonce) {
            return Err("Invalid service signature".to_string());
        }

        let mut sessions = self.sessions.write().unwrap();
        let session = sessions.get_mut(&req.user_id)
            .ok_or_else(|| "User session not found".to_string())?;

        // Nonce replay protection: ensure nonce is strictly greater
        if req.nonce <= session.last_payment_nonce {
            return Err("Replay detected: nonce too old".to_string());
        }

        // Apply the credit to user balance
        let new_balance = self.calculate_new_balance(session.balance_cents, req.amount_cents)?;
        session.balance_cents = new_balance;
        session.last_payment_nonce = req.nonce;

        // Recalculate tier based on current balance
        self.recalculate_tier(session);

        let mut log = self.payment_log.write().unwrap();
        log.push((req.user_id.clone(), req.amount_cents, req.nonce));

        Ok(format!("Payment processed. New balance: {}", new_balance))
    }

    /// Balance calculation with overflow protection.
    /// Uses checked arithmetic to prevent overflow exploits.
    fn calculate_new_balance(&self, current: i64, credit: i64) -> Result<i64, String> {
        // Reject negative credits - refunds must go through separate refund flow
        if credit < 0 {
            return Err("Negative amounts not permitted in payment flow".to_string());
        }
        let result = current.checked_add(credit)
            .ok_or_else(|| "Balance overflow detected".to_string())?;
        Ok(result)
    }

    fn recalculate_tier(&self, session: &mut UserSession) {
        if session.balance_cents >= 100_000 {
            session.tier = SubscriptionTier::Enterprise;
        } else if session.balance_cents >= 10_000 {
            session.tier = SubscriptionTier::Premium;
        } else {
            session.tier = SubscriptionTier::Free;
        }
    }

    pub fn send_message(&self, msg: &ChatMessage) -> Result<(), String> {
        let sessions = self.sessions.read().unwrap();
        let session = sessions.get(&msg.sender_id)
            .ok_or_else(|| "Not authenticated".to_string())?;

        if msg.is_premium_channel && session.tier == SubscriptionTier::Free {
            return Err("Premium channel requires paid subscription".to_string());
        }

        // Message delivery logic would go here
        Ok(())
    }

    fn verify_service_auth(&self, signature: &[u8], user_id: &str, amount: i64, nonce: u64) -> bool {
        // Verify HMAC-SHA256 signature against the known service key
        if let Some(key) = self.service_keys.get("payment_service") {
            let expected = self.compute_hmac(key, user_id, amount, nonce);
            constant_time_eq(&expected, signature)
        } else {
            false
        }
    }

    fn compute_hmac(&self, key: &[u8], user_id: &str, amount: i64, nonce: u64) -> Vec<u8> {
        // Real keyed HMAC-SHA256 over the canonical message.
        let mut mac = HmacSha256::new_from_slice(key)
            .expect("HMAC can take a key of any size");
        mac.update(user_id.as_bytes());
        mac.update(&amount.to_le_bytes());
        mac.update(&nonce.to_le_bytes());
        mac.finalize().into_bytes().to_vec()
    }
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_negative_payment_rejected() {
        let mut keys = HashMap::new();
        keys.insert("payment_service".to_string(), b"secret_key_123".to_vec());
        let server = ChatServer::new(keys);

        server.authenticate_session("alice", b"token").unwrap();

        // Legitimate payment
        let sig = server.compute_hmac(b"secret_key_123", "alice", 50000, 1);
        let req = PaymentRequest {
            user_id: "alice".to_string(),
            amount_cents: 50000,
            nonce: 1,
            service_signature: sig,
            channel_id: "general".to_string(),
        };
        server.process_payment(&req).unwrap();

        // Negative amount payment - must be rejected
        let sig2 = server.compute_hmac(b"secret_key_123", "alice", -50000, 2);
        let req2 = PaymentRequest {
            user_id: "alice".to_string(),
            amount_cents: -50000,
            nonce: 2,
            service_signature: sig2,
            channel_id: "general".to_string(),
        };
        let result = server.process_payment(&req2);
        assert!(result.is_err());
    }
}
